package org.marketreview.nativeapp;
import org.json.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
final class MigrationStatusModel {
 static void require(boolean b,String why){if(!b)throw new IllegalArgumentException(why);}
 static String json(JSONObject o)throws Exception{String s=SourceAnalysisPacket.json(o);require(s.getBytes(StandardCharsets.UTF_8).length<=25*1024*1024,"迁移快照超过25MiB；未截断");return s;}
 static JSONObject validate(JSONObject o)throws Exception{json(o);require(o.optString("schema").equals("native-migration-status/v1")&&o.optJSONArray("entries")!=null,"迁移快照schema/entries无效");Set<String> ids=new HashSet<>();JSONArray rows=o.getJSONArray("entries");for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);require(r.opt("id") instanceof String&&!r.getString("id").trim().isEmpty()&&ids.add(r.getString("id")),"审查项身份缺失或重复");}return o;}
 static String field(JSONObject o,String k){Object v=o.opt(k);if(v instanceof String&&!((String)v).trim().isEmpty())return (String)v;if(v instanceof Boolean)return (Boolean)v?"是":"否";if(v instanceof JSONArray){List<String> a=new ArrayList<>();JSONArray rows=(JSONArray)v;for(int i=0;i<rows.length();i++)if(rows.opt(i) instanceof String)a.add(rows.optString(i));if(!a.isEmpty())return String.join(" / ",a);}return "未知";}
 static String dimension(JSONObject o,String k){return field(o,k.equals("implementation")&&!o.has(k)?"nativeStatus":k);}
 static List<String> options(JSONObject o,String k)throws Exception{Set<String> values=new TreeSet<>();JSONArray rows=o.getJSONArray("entries");for(int i=0;i<rows.length();i++)values.add(dimension(rows.getJSONObject(i),k));return new ArrayList<>(values);}
 static JSONArray filter(JSONObject o,JSONObject q)throws Exception{validate(o);JSONArray rows=o.getJSONArray("entries"),out=new JSONArray();String search=q.optString("search").trim().toLowerCase(Locale.ROOT);for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);boolean matches=true;for(String k:new String[]{"platform","module","implementation","acceptance","externalBlocker"}){String wanted=q.optString(k);if(!wanted.isEmpty()&&!wanted.equals(dimension(r,k)))matches=false;}if(matches&&(search.isEmpty()||r.toString().toLowerCase(Locale.ROOT).contains(search)))out.put(r);}return out;}
 static String summary(JSONObject o)throws Exception{int partial=0,pending=0,accepted=0,unknown=0;JSONArray rows=o.getJSONArray("entries");for(int i=0;i<rows.length();i++){String s=rows.getJSONObject(i).optString("nativeStatus");if(s.equals("部分实现")||s.equals("partial"))partial++;else if(s.equals("待迁移")||s.equals("pending"))pending++;else if(s.equals("fullyAccepted")||s.equals("完整验收"))accepted++;else unknown++;}return "冻结迁移快照 · 非实时总进度\n版本："+field(o,"version")+" · 时点："+field(o,"asOf")+"\n来源："+field(o,"snapshotSource")+" · 源版本："+field(o,"sourceHead")+"\n注入时间："+field(o,"capturedAt")+" · 陈旧性："+field(o,"stale")+"\n"+rows.length()+"审查项 · "+partial+"部分实现 / "+pending+"待迁移 / "+accepted+"完整验收 / "+unknown+"未知\n"+field(o,"scopeNote")+"\n代码、确定性检查、真实来源、人工验收和ARM分别记录；入口存在不代表完成。";}
 static List<String> references(JSONObject r)throws Exception{List<String> out=new ArrayList<>();JSONArray a=r.optJSONArray("evidenceRefs");if(a!=null){for(int i=0;i<a.length();i++)if(a.opt(i) instanceof String&&!a.getString(i).trim().isEmpty())out.add(a.getString(i));}else if(r.opt("evidence") instanceof String&&!r.optString("evidence").trim().isEmpty())out.add(r.getString("evidence"));return out;}
 static String detail(JSONObject r)throws Exception{StringBuilder out=new StringBuilder(field(r,"id")+" · "+field(r,"title")+"\n平台："+field(r,"platform")+" · 模块："+field(r,"module")+"\n实现："+dimension(r,"implementation")+" · 验收："+field(r,"acceptance")+"\n外部阻断："+field(r,"externalBlocker")+"\n\n完整范围与缺口\n"+field(r,"scope")+"\n\n原验收说明\n"+field(r,"verification")+"\n迁移决策\n"+field(r,"decision")+"\n\n验证维度（缺失为未知）\n");JSONObject dimensions=r.optJSONObject("verificationDimensions");if(dimensions==null)dimensions=new JSONObject();for(String k:new String[]{"code","fixture","realSource","manual","arm"})out.append(k.equals("code")?"代码存在":k.equals("fixture")?"确定性检查":k.equals("realSource")?"真实来源":k.equals("manual")?"人工验收":"ARM真机").append("：").append(field(dimensions,k)).append('\n');return out+"\n证据引用（由宿主白名单解析）\n"+(references(r).isEmpty()?"未知（未提供引用）":String.join("\n",references(r)))+"\n\n完整原始审查记录\n"+json(r);}
 static String proof(JSONObject r){return "宿主返回的证据；版本和可用性以返回元数据为准\n来源："+field(r,"source")+"\n时点："+field(r,"asOf")+"\n可用："+field(r,"available")+"\n说明："+field(r,"message")+"\n\n"+field(r,"text");}
}

